<?php
/** سفارش‌های فروشگاه‌ها: وضعیت، خروج کالا و موارد نیازمند بررسی. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Jalali,Money,Request};
use Agah\Erp\Modules\Connect\ConnectService;
if(!defined('ABSPATH'))exit;
$status=Request::str('get','status',12);$data=ConnectService::ordersPage($cid,$status,Request::int('get','pg',1));
?>
<section class="erp-card"><h2>سفارش‌های فروشگاه</h2>
<form method="get" class="erp-filter"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="connect_orders"><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(ConnectService::STATES as $k=>$label): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($status,$k); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button type="submit" class="btn btn-outline">نمایش</button></form>
<p>واحد: <?php echo esc_html(Money::unitLabel(Ctx::unit())); ?>. «خروج کالا» فاکتور فروش صادر می‌کند، موجودی را از همان رزرو کم می‌کند و پیش‌دریافت را به فاکتور می‌زند.</p>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>فروشگاه</th><th>سفارش</th><th>خریدار</th><th>مبلغ پرداخت‌شده</th><th>وضعیت</th><th>فاکتور</th><th>توضیح</th><th>عملیات</th></tr></thead><tbody>
<?php foreach($data['rows'] as $o): ?><tr><td><?php echo esc_html($o['store']); ?></td><td dir="ltr"><?php echo esc_html($o['order_ref']); ?></td><td><?php echo esc_html($o['party_name']); ?></td><td><?php echo esc_html(Money::fmt((int)$o['paid_amount'],Ctx::unit())); ?></td><td><?php echo esc_html(ConnectService::STATES[$o['status']]??$o['status']); ?><?php if($o['refund_due']): ?><br><strong>استرداد وجه لازم است</strong><?php endif; ?><?php if((int)$o['refunded_amount']>0): ?><br>مسترد: <?php echo esc_html(Money::fmt((int)$o['refunded_amount'],Ctx::unit())); ?><?php endif; ?></td><td><?php echo $o['invoice_number']?esc_html(Money::toFa($o['invoice_number'])):'—'; ?></td><td class="erp-wrap"><?php echo esc_html($o['review_reason']); ?></td><td>
<?php if(in_array($o['status'],['paid','review'],true)&&!(int)$o['refunded_amount']&&Ctx::can('connect.edit')): ?><form method="post" class="erp-inline-form"><?php self::form('module_connect_dispatch',$cid,'connect_orders',$o['id']); ?><button type="submit" class="btn btn-primary btn-sm">خروج کالا و صدور فاکتور</button></form><?php endif; ?>
<?php if(in_array($o['status'],['review','cancelled'],true)&&($o['status']==='review'||$o['refund_due'])&&Ctx::can('connect.edit')): ?><form method="post" class="erp-inline-form"><?php self::form('module_connect_close',$cid,'connect_orders',$o['id']); ?><input name="note" maxlength="300" required placeholder="دلیل بستن (مثلاً استرداد دستی ثبت شد)" aria-label="دلیل بستن سفارش"><button type="submit" class="btn btn-outline btn-sm" data-confirm="سفارش بسته شود؟ رزرو آزاد می‌شود و دیگر خودکار پیگیری نمی‌شود.">بستن سفارش</button></form><?php endif; ?>
</td></tr><?php endforeach; ?></tbody></table></div>
<?php self::pages($data['pages'],$data['page']); ?></section>
<?php $refunds=ConnectService::refunds($cid); if($refunds): ?>
<section class="erp-card"><h2>استرداد و مرجوعی فروشگاه</h2>
<p>استرداد وجه و برگشت کالا دو رویداد جدا هستند: وجه همان لحظه در خزانه ثبت می‌شود، ولی موجودی فقط وقتی زیاد می‌شود که کالا واقعاً به انبار برسد و «دریافت فیزیکی کالا» ثبت شود.</p>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>فروشگاه</th><th>سفارش</th><th>شناسهٔ استرداد</th><th>مرحله</th><th>مبلغ</th><th>وضعیت</th><th>برگشت فروش</th><th>توضیح</th><th>عملیات</th></tr></thead><tbody>
<?php foreach($refunds as $r): ?><tr><td><?php echo esc_html($r['store']); ?></td><td dir="ltr"><?php echo esc_html($r['order_ref']); ?></td><td dir="ltr"><?php echo esc_html($r['refund_ref']); ?></td><td><?php echo $r['stage']==='before'?'پیش از خروج کالا':'پس از خروج کالا'; ?></td><td><?php echo esc_html(Money::fmt((int)$r['amount'],Ctx::unit())); ?></td><td><?php echo esc_html(ConnectService::REFUND_STATES[$r['status']]??$r['status']); ?></td><td><?php echo $r['return_number']?esc_html(Money::toFa($r['return_number'])):'—'; ?></td><td class="erp-wrap"><?php echo esc_html($r['note']); ?></td><td>
<?php if(Ctx::can('connect.edit')&&$r['status']==='awaiting'&&Ctx::can('sale_return.create')): ?><form method="post" class="erp-inline-form"><?php self::form('module_connect_receive',$cid,'connect_orders',$r['id']); self::input('doc_date','تاریخ دریافت',Jalali::format(Jalali::today(),false),'text','required data-jalali maxlength="10"'); ?><button type="submit" class="btn btn-primary btn-sm" data-confirm="کالا واقعاً دریافت شده است؟ برگشت فروش صادر و موجودی انبار زیاد می‌شود.">دریافت فیزیکی کالا</button></form><?php endif; ?>
<?php if(Ctx::can('connect.edit')&&in_array($r['status'],['awaiting','review'],true)): ?><form method="post" class="erp-inline-form"><?php self::form('module_connect_resolve',$cid,'connect_orders',$r['id']); ?><input name="note" maxlength="300" required placeholder="توضیح (مثلاً کالا برنمی‌گردد؛ سند اصلاحی ثبت شد)" aria-label="توضیح تعیین‌تکلیف"><button type="submit" class="btn btn-outline btn-sm" data-confirm="این استرداد بدون اقدام خودکار دیگر بسته شود؟">تعیین‌تکلیف</button></form><?php endif; ?>
</td></tr><?php endforeach; ?></tbody></table></div></section>
<?php endif; ?>
